import Model from 'flarum/common/Model';
export default class LogFile extends Model {
  fileName() {
    return Model.attribute('fileName').call(this);
  }
  relativePath() {
    return Model.attribute('relativePath').call(this);
  }
  fullPath() {
    return Model.attribute('fullPath').call(this);
  }
  size() {
    return Model.attribute('size').call(this);
  }
  modified() {
    return Model.attribute('modified', Model.transformDate).call(this);
  }
  content() {
    return Model.attribute('content').call(this);
  }
}
flarum.reg.add('ianm-log-viewer', 'admin/models/LogFile', LogFile);